"""Presentation for account operations and global storage controls."""

USER_TOOLS = r'''<section class="form-card"><h2>Find users</h2><form method="get" class="feature-toolbar"><input class="text-input" name="q" value="{{ search_query }}" placeholder="Username or user ID" aria-label="Search users"><select class="text-input" name="status" aria-label="Account status">{% for value,label in [('','All statuses'),('active','Enabled and valid'),('disabled','Disabled'),('expired','Expired'),('pending','Awaiting activation')] %}<option value="{{ value }}" {% if status_filter == value %}selected{% endif %}>{{ label }}</option>{% endfor %}</select><select class="text-input" name="mode" aria-label="Auth method">{% for value,label in [('','All auth methods'),('password','Password'),('product_key','Product key'),('both','Both')] %}<option value="{{ value }}" {% if mode_filter == value %}selected{% endif %}>{{ label }}</option>{% endfor %}</select><button class="button" type="submit">Filter</button><a class="plain" href="/auth/apps/{{ auth_app.id }}">Reset</a></form><p class="hint">Showing {{ users|length }} of {{ total_users }} users.</p></section>
<section class="form-card"><details><summary>Generate multiple accounts</summary><form class="feature-toolbar" method="post" action="/auth/apps/{{ auth_app.id }}/users/batch-create"><input type="hidden" name="csrf" value="{{ csrf }}"><label>Accounts<input class="text-input" name="count" type="number" min="1" max="100" value="10" required></label><label>Auth method<select class="text-input" name="auth_mode"><option value="product_key">Product key</option><option value="password">Password</option><option value="both">Both</option></select></label><label>License<select class="text-input" name="duration_days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="365">365 days</option><option value="0">Never expires</option></select></label><button class="button primary" type="submit">Generate accounts</button></form><p class="hint">Each user gets unique credentials, shown once. Timed licenses start on first authentication.</p></details></section>
<section class="form-card bulk-toolbar"><form id="bulk-users" method="post" action="/auth/apps/{{ auth_app.id }}/users/bulk"><input type="hidden" name="csrf" value="{{ csrf }}"><div class="feature-toolbar"><label class="select-users"><input type="checkbox" id="select-all-users"> Select displayed users</label><select class="text-input" name="action" aria-label="Bulk action"><option value="enable">Enable</option><option value="disable">Disable</option><option value="extend">Extend license</option><option value="delete">Delete</option></select><label>Extend by days<input class="text-input" type="number" name="days" value="30" min="1" max="36500" required></label><button class="button" type="submit">Apply to selected</button><span id="selected-count" class="hint">0 selected</span></div></form><p class="hint">Extending a never-expiring account gives it an expiration date from today. Pending licenses gain days before activation.</p></section>'''


def enhance_auth(source):
    source = source.replace('<label>Expires (UTC, optional)', '<label>License duration<select class="text-input" name="duration_days"><option value="0">Use date below / never expires</option><option value="7">7 days from first login</option><option value="30">30 days from first login</option><option value="365">365 days from first login</option></select></label><label>Expires (UTC, optional)', 1)
    source = source.replace('<div class="section-title">Users · {{ users|length }}</div>', USER_TOOLS+'<div class="section-title">Users · {{ users|length }}</div>', 1)
    source = source.replace('<strong>{{ user.username }}</strong>', '<label class="user-select"><input form="bulk-users" type="checkbox" name="user_ids" value="{{ user.id }}" aria-label="Select {{ user.username }}"></label><strong>{{ user.username }}</strong>', 1)
    source = source.replace('{% if user.expires_at %}<div class="hint">', '{% if user.duration_days and not user.activated_at %}<div class="hint">{{ user.duration_days }}-day license · starts on first login</div>{% endif %}{% if user.expires_at %}<div class="hint">', 1)
    source = source.replace('{% else %}<div class="hint">No expiration</div>', '{% elif not user.duration_days %}<div class="hint">No expiration</div>', 1)
    return source


STORAGE_CARD = r'''<section class="form-card settings-card storage-card"><div class="settings-card-heading"><span class="settings-symbol" aria-hidden="true">▤</span><div><h2>Storage · whole panel</h2><p class="muted">Messages, attachments, auth data, and database files.</p></div></div><div class="storage-stats"><div><strong>{{ storage.free_gb }} GiB</strong><span>Disk space left</span></div><div><strong>{{ storage.data_mb }} MiB</strong><span>Panel data on disk</span></div><div><strong>{{ storage.messages }}</strong><span>Stored messages</span></div><div><strong>{{ storage.files }}</strong><span>Attachments · {{ storage.attachment_mb }} MiB</span></div></div><progress class="storage-progress" max="100" value="{{ storage.used_percent }}" aria-label="Disk usage">{{ storage.used_percent }}%</progress><p class="hint">{{ storage.used_percent }}% of the {{ storage.total_gb }} GiB server disk is used.</p>{% if storage_notice %}<div class="notice" role="status">{{ storage_notice }}</div>{% endif %}<form class="settings-form" method="post" action="/settings/storage"><input type="hidden" name="csrf" value="{{ csrf }}"><label class="checkbox-row"><input type="checkbox" name="auto_backup" {% if storage.auto_enabled %}checked{% endif %}> Automatic Telegram backups below 10 GiB free</label><p class="hint">Every five minutes, back up the 20 newest webhook users across the panel. Histories are sent as JSON with their attachments. Large files are split into parts. Unchanged users are skipped. Local data stays on the server.</p><label>Automatic retention (days; 0 keeps everything)<input class="text-input" type="number" name="retention_days" value="{{ storage.retention_days }}" min="0" max="36500" required></label><p class="hint">Enabling retention deletes messages and attachments older than this age across all webhooks. Auth users are retained. Retention pauses while disk space is below 10 GiB.</p><button class="button primary" type="submit">Save storage options</button></form><div class="notice">{{ storage.backup_status }}{% if storage.backup_time %}<br>Last completed check: {{ storage.backup_time|float|datetime }}{% endif %}</div><details><summary>Clean up old messages now</summary><form class="settings-input-row" method="post" action="/settings/storage/cleanup" onsubmit="return confirm('Permanently delete messages and their files older than the selected age across ALL webhooks?')"><input type="hidden" name="csrf" value="{{ csrf }}"><label>Older than days<input class="text-input" type="number" name="days" min="1" max="36500" value="30" required></label><button class="delete" type="submit">Delete old messages</button></form></details></section>'''
